 # Relations are directions of reading/critique, never an assertion of shared doctrine.
 rels=[]
 def relation(id,a,b,kind,title,text,refs):
  rels.append(dict(id=id,fromId=a,toId=b,type=kind,title=title,summary=text,sources=refs))
 relation('socrates-plato','socrates','plato','learning','交谈传统与对话写作','柏拉图与苏格拉底的关联有多种古代记载，但对话中的苏格拉底是经过作者组织的角色。不能把所有台词当成现场速记，也不能抹掉柏拉图自己的哲学问题。',[P,source('socrates','苏格拉底')])
 relation('plato-aristotle','plato','aristotle','learning','学园学习与形式论的分歧','亚里士多德曾在柏拉图学园学习，又对形式与个物分离等问题提出批评。此线同时标示真实学习关联与思想分歧，不等于学生照搬老师的全部主张。',[A,book(67,'学园与柏拉图对话')])
 relation('plato-plotinus','plato','plotinus','reception','晚期柏拉图传统的重新解释','普罗提诺从柏拉图文本发展出自己的理智、灵魂及最高原则讨论，二人并不同时代。接受史不应画成直接面授，也不能把晚期体系原样归给柏拉图。',[Plot,P])
 relation('plotinus-augustine','plotinus','augustine','reception','柏拉图派书籍与基督徒解释','奥古斯丁回顾自己阅读柏拉图派书籍，但相关译本的范围和辨认仍有研究问题。这条线标示文本传统的接受与重组，不声称二人见面或观点完全一致。',[August,book(193,'奥古斯丁及柏拉图传统')])
 relation('aristotle-boethius','aristotle','boethius','translation','逻辑译注进入拉丁教学','波埃修翻译、注释亚里士多德部分逻辑作品，后世拉丁教学因此拥有重要资源。实际完成的译注范围，与原先可能设想的庞大计划应分开。',[B,book(209,'波埃修')])
 relation('aristotle-avicenna','aristotle','avicenna','reception','阿拉伯语哲学中的系统重构','伊本·西那借已有翻译和讨论重组逻辑、自然与形而上学问题，并发展自己的论证。他不是古希腊文本的无变化传声筒，这里也不把全部中介省略成直接接触原稿。',[source('ibn-sina','伊本·西那'),source('arabic-islamic-greek','希腊来源与阿拉伯语哲学')])
 relation('aristotle-averroes','aristotle','averroes','reception','注释体裁中的解释与论辩','伊本·鲁世德的亚里士多德注释有不同体裁、对象和问题。注释是一种带有判断的解释实践，而不是只在原文旁加一个同义词。',[source('ibn-rushd','伊本·鲁世德'),A])
 relation('aristotle-aquinas','aristotle','aquinas','reception','自然与实践论题进入神学论证','阿奎那接受并改造亚里士多德的许多区分，同时不接受其所有结论。理性资源与基督教启示之间的安排，需要逐项阅读，不能仅凭一个继承标签推知答案。',[T,summa])
 relation('avicenna-aquinas','avicenna','aquinas','reception','拉丁接受中的引用与改写','阿奎那通过拉丁可得的作品讨论伊本·西那提出的问题，既使用也批评相关论证。此线是文本接受，不表示双方属于同一个宗教或思想学派。',[T,source('arabic-islamic-influence','阿拉伯语思想的拉丁接受')])
 relation('averroes-aquinas','averroes','aquinas','critique','理智及解释权的争论','阿奎那批评与伊本·鲁世德相关的理智解释，同时也借助其注释资源。争论要区分原作者、拉丁译本及拉丁读者的主张，不能把后者全部倒归原作者。',[T,source('arabic-islamic-influence','阿拉伯语思想的拉丁接受')])
 relation('boethius-abelard','boethius','abelard','reception','逻辑文本与共相问题的延续','阿伯拉尔在已有拉丁逻辑资源中提出自己的共相解释。此处标示文本和问题的传递，并不把数百年的学校历史误画成一个无中介的师生关系。',[U,Ab])
 relation('augustine-anselm','augustine','anselm','reception','信仰中寻求理解的重写','安瑟伦接续奥古斯丁传统的关切，又在特定修院环境中组织新的论证。共同关注信仰与理解，不等于二人的所有证明和认识论都相同。',[N,book(226,'安瑟伦的信仰与理解')])
 relation('augustine-eriugena','augustine','eriugena','reception','拉丁权威与希腊译介的综合','爱留根纳使用奥古斯丁等拉丁作者，同时引入希腊基督徒文本。他的综合有新的选择和争议，不是只沿单一西方传统自然生长。',[E,book(218,'爱留根纳的翻译与综合')])
 relation('anselm-aquinas','anselm','aquinas','critique','从概念与从经验分析出发的差别','阿奎那对从关于上帝的概念直接证明存在持不同判断，采用变化和依赖等分析。这里标示论证分歧，不暗示安瑟伦是其老师，也不将五路与一种现代物理模型等同。',[T,N,book(251,'两种论证起点的比较')])
 relation('aquinas-scotus','aquinas','duns-scotus','critique','经院内部的不同方案','邓司各脱与阿奎那在个体化、存在概念等问题上有不同论证，不能将此概括为一个人简单废除另一个人的体系。箭头表示被讨论立场与后续回应的方向。',[S,T,U])
 relation('scotus-ockham','duns-scotus','ockham','critique','共同本性与普遍概念的争议','奥卡姆不沿用邓司各脱的全部本体论安排。两人的差异要放在共同本性、个别存在者和概念功能中说明，不能声称存在已经证实的直接面授关系。',[O,S,U])
 relation('plato-ficino','plato','ficino','translation','柏拉图作品的拉丁翻译与解释','费奇诺译本为拉丁读者组织柏拉图作品提供资源，翻译和注释本身带有十五世纪的问题。古代对话、译文和费奇诺的宗教哲学须分别阅读。',[Fi,P])
 relation('plotinus-ficino','plotinus','ficino','translation','《九章集》的拉丁译注','费奇诺翻译和注释普罗提诺，形成新的文艺复兴接受层。对古典思想的重读并非只靠古人再现，也依赖手稿、编辑与印刷劳动。',[Fi,Plot])
 relation('petrarch-valla','petrarch','valla','context','共同的人文主义问题背景','两者可放在古典语言、道德与教育实践中比较，此线只标共同背景。并未据此声称瓦拉是彼特拉克学生，也不把不同人文主义者合成统一教义。',[source('lorenzo-valla','瓦拉'),book(286,'人文主义语境')])
 relation('valla-erasmus','valla','erasmus','reception','语文学与新约研究','伊拉斯谟关注并出版瓦拉的新约注释，语文学由此继续进入宗教文本研究。继承语言批判的方法，不意味着每一项神学或政治立场都被继承。',[source('erasmus','伊拉斯谟'),source('lorenzo-valla','瓦拉')])
 relation('montaigne-descartes','montaigne','descartes','context','判断与怀疑的不同用法','随笔中的自我检视与笛卡尔的方法怀疑可作问题比较；这条线不据相似主题就断言直接师承或确定的单向影响。二者的写作目的与论证结构不同。',[M,Desc,book(299,'蒙田与怀疑传统')])
 relation('bacon-descartes','bacon','descartes','context','知识改革的并行道路','培根和笛卡尔都批评某些现成知识，研究组织、经验安排与求确定性的路径却不同。此线是并行比较，不表示培根指导笛卡尔或单一科学方法已经统一。',[F,Desc])
 relation('epicurus-stoa','epicurus','zeno-stoa','context','希腊化伦理的不同方向','伊壁鸠鲁传统与早期斯多亚可围绕快乐、德性和判断比较；此线只标问题的并列，不表示二人构成一个共同学派，或存在已核实的直接师承。',[ethics,source('epicurus','伊壁鸠鲁'),source('stoicism','斯多亚主义')])
 relation('aristotle-maimonides','aristotle','maimonides','reception','哲学资源与犹太经文解释','迈蒙尼德在阿拉伯语学术环境中讨论亚里士多德传统与经文解释。接受、保留和批评需要分题阅读，不能把作者说成单纯复述希腊哲学。',[source('maimonides','迈蒙尼德'),book(232,'跨宗教哲学环境')])
 relation('cusa-ficino','cusa','ficino','context','十五世纪柏拉图传统的不同实践','库萨的认识限度问题与费奇诺的译注活动，可放在十五世纪柏拉图传统中比较。此线不宣称库萨指导费奇诺，也不把问题相近视为已经证明的直接影响。',[C,Fi])
 relation('dionysius-eriugena','pseudo-dionysius','eriugena','translation','希腊基督徒文本的拉丁翻译','爱留根纳翻译伪狄奥尼修斯的著作并作解释，让这些希腊文本进入新的拉丁语争论。原作、译文与爱留根纳自己的体系是三个层次，不能把译者的全部观点归给原作者。',[D,E,book(218,'翻译及爱留根纳')])
